var k = 0
for n in ["COMMAND", "MOVEMENT", "SHOOTING", "CHARGE", "FIGHT", "SCORING"]:
	if tree.root.get_node_or_null("/root/Main/PhaseStrip/PhaseBar/PhasePill_" + n) != null:
		k += 1
return k

var words = []
for n in ["COMMAND", "MOVEMENT", "SHOOTING", "CHARGE", "FIGHT", "SCORING"]:
	words.append(tree.root.get_node("/root/Main/PhaseStrip/PhaseBar/PhasePill_" + n + "/Label").text)
return " > ".join(words)

var bar = tree.root.get_node("/root/Main/PhaseStrip/PhaseBar")
var strip = bar.get_parent()
var floor_y = tree.root.get_visible_rect().size.y - PlayerTurnBorder.BORDER_THICKNESS
var bad = []
for c in bar.get_children():
	if String(c.name).begins_with("PhasePill_"):
		var r = c.get_global_rect()
		if r.position.y <= strip.global_position.y or r.end.y > floor_y:
			bad.append(String(c.name) + str(r))
return bad.size()

var bar = tree.root.get_node("/root/Main/PhaseStrip/PhaseBar")
var s = bar.get_script()
var bad = []
for c in bar.get_children():
	if String(c.name).begins_with("PhasePill_"):
		var l = c.get_node("Label")
		var tw = s.PILL_FONT.get_string_size(l.text, HORIZONTAL_ALIGNMENT_LEFT, -1, s.FONT_SIZE).x
		if l.size.x < tw or l.clip_text or l.text_overrun_behavior != TextServer.OVERRUN_NO_TRIMMING:
			bad.append(l.text)
return bad.size()

var k = 0
for n in ["MOVEMENT", "SHOOTING", "CHARGE", "FIGHT", "SCORING"]:
	if is_equal_approx(tree.root.get_node("/root/Main/PhaseStrip/PhaseBar/PhasePill_" + n).modulate.a, 0.4):
		k += 1
return k

var strip = tree.root.get_node("/root/Main/PhaseStrip")
var bar = strip.get_node("PhaseBar")
var sig = "strip" + str(strip.get_global_rect()) + "|bar" + str(bar.get_global_rect())
for c in bar.get_children():
	sig += "|" + String(c.name) + str(c.get_global_rect())
for p in ["/root/Main/GameLogPanel", "/root/Main/HUD_Right", "/root/Main/HUD_Bottom"]:
	var n = tree.root.get_node_or_null(p)
	sig += "|" + p + (str(n.get_global_rect()) if n != null else "<none>")
bar.set_meta("t04_layout_command", sig)
return sig.length() > 0

var img = Image.load_from_file(ProjectSettings.globalize_path("user://test_results/scenarios/T04_phase_bar_T04_command_before.png"))
if img == null:
	return "no screenshot"
var bar = tree.root.get_node("/root/Main/PhaseStrip/PhaseBar")
var lstar = func(c: Color) -> float:
	var l = c.srgb_to_linear()
	var y = 0.2126 * l.r + 0.7152 * l.g + 0.0722 * l.b
	return 116.0 * pow(y, 1.0 / 3.0) - 16.0 if y > 0.008856 else 903.3 * y
var L = {}
for c in bar.get_children():
	if not String(c.name).begins_with("PhasePill_"):
		continue
	var r = c.get_global_rect()
	var cy = int(r.position.y + r.size.y / 2.0)
	var sum = 0.0
	for x in [int(r.position.x) + 5, int(r.end.x) - 6]:
		for dy in [-2, 0, 2]:
			sum += lstar.call(img.get_pixel(x, cy + dy))
	L[String(c.name).trim_prefix("PhasePill_")] = snappedf(sum / 6.0, 0.1)
var a = L["COMMAND"]
for n in L:
	if n != "COMMAND" and L[n] + 8.0 >= a:
		return "active not brightest: " + str(L)
for c in []:
	for f in ["MOVEMENT", "SHOOTING", "CHARGE", "FIGHT", "SCORING"]:
		if absf(L[c] - L[f]) <= 20.0:
			return "completed vs future too close: " + str(L)
DebugLogger.info("[T04_phase_bar] rendered pill L* (P1 Command): " + str(L))
return "ok"

